<?php namespace App\Services; use App\Repositories\LancamentoRepository; class FiadoService { public function __construct(private LancamentoRepository $repo,private ClienteService $clientes,private AuditoriaService $audit) {} public function create(array $data):array { $c=$this->clientes->owned($data['cliente_id']); abort_unless($c,404);$before=$this->clientes->balance($c['id']);$next=$before+(float)$data['valor'];$canOverride=in_array(session('perfil'),['dono','gerente']);if(($c['status']??'ativo')==='bloqueado'&&!$canOverride) throw new \DomainException('Cliente bloqueado. Apenas dono ou gerente podem lançar.');if($next>(float)$c['limite_fiado']&&!$canOverride) throw new \DomainException('O lançamento ultrapassa o limite de fiado deste cliente.'); $l=$this->repo->create(array_merge($data,['loja_id'=>session('loja_id'),'usuario_id'=>session('usuario_id'),'status'=>'aberto','tipo'=>$data['tipo']??'compra']));$this->audit->log('Lançamento criado','lancamento',$l['id'],'Compra de R$ '.number_format($l['valor'],2,',','.'));return [$l,$before,$next];} }
